import re
import json
from taf.ul.sc.perf.tc import tc


class RTGKPIStats(object):
    _base_marker = "DB->{data_type} properties->device:{device_name}->cell:{sector}->"
    _procedure_marker = "{}{}".format(_base_marker, "procedure:{procedure}->{stats_name}")
    _throughput_marker = "{}{}".format(_base_marker, "protocol:{protocol}->direction:{direction}->{stats_name}")
    _sector_marker = "{}{}".format(_base_marker, "{stats_name}")

    def __init__(self, json_file):
        self.json_file = json_file
        self.stats = self._load_stats_file()

    def _load_stats_file(self):
        with open(self.json_file, 'r') as file_handler:
            content = json.load(file_handler)
        return content

    def add_success_rate_stats(self):
        # 1 (100.0%)
        re_percentage_value = re.compile(r"(?P<COUNT>\d+)\s+\((?P<VALUE>\d+\.\d+)%\)")

        static_marker_params = [
            {
                'data_type': 'integer',
                'stats_name': 'type:count->signaling procedure'
            },
            {
                'data_type': 'percentage',
                'stats_name': 'type:rate->signaling procedure'
            },
        ]

        parser = ParserConfig(build_method="procedure",
                              path_to_enb_stats='[procedure]["success"]["VALUES"]')

        self._add_rtg_stats(data=self.stats["sigProc-C"]["data"],
                            parser=parser,
                            static_marker_params=static_marker_params,
                            marker_template=RTGKPIStats._procedure_marker,
                            pattern=re_percentage_value)

    def add_ue_failures_stats(self):
        static_marker_params = [
            {
                'data_type': 'integer',
                'stats_name': 'UE failures count'
            },
        ]
        parser = ParserConfig(build_method="procedure",
                              path_to_enb_stats='[procedure]["VALUES"]')

        self._add_rtg_stats(data=self.stats["ueFail-C"]["data"],
                            parser=parser,
                            static_marker_params=static_marker_params,
                            marker_template=RTGKPIStats._procedure_marker,
                            add_zero_values=True)

    def add_rach_stats(self):
        static_marker_params = [
            {
                'data_type': 'integer',
                'stats_name': 'RACH count'
            },
        ]

        parser = ParserConfig(build_method="procedure",
                              path_to_enb_stats='[procedure]["VALUES"]')

        data = self.stats["Scheduler_instance_Per CellSum-C"]["data"].get("Scheduler")
        if data:
            self._add_rtg_stats(data=data,
                                parser=parser,
                                static_marker_params=static_marker_params,
                                marker_template=RTGKPIStats._procedure_marker)

    def add_bearers_stats(self):
        static_marker_params = [
            {
                'data_type': 'integer',
                'stats_name': 'bearers allocations failure'
            },
        ]

        parser = ParserConfig(build_method="sector")
        if self.stats.get("brTotal-C"):
            self._add_rtg_stats(data=self.stats["brTotal-C"]["data"]["Total"]["Failure"]["VALUES"],
                                parser=parser,
                                static_marker_params=static_marker_params,
                                marker_template=RTGKPIStats._sector_marker)

    def add_throughput_success_rate_stats(self):
        # 34296949 (92.87%)
        re_percentage_value = re.compile(r"\d+\s+\((?P<VALUE>\d+\.\d+)%\)")

        static_marker_params = [
            {
                'data_type': 'decimal',
                'stats_name': 'throughput success rate'
            },
        ]
        parser = ParserConfig(build_method="throughput",
                              path_to_enb_stats='[protocol][direction]["VALUES"]')

        self._add_rtg_stats(data=self.stats["prPack-C"]["data"],
                            parser=parser,
                            static_marker_params=static_marker_params,
                            marker_template=RTGKPIStats._throughput_marker,
                            pattern=re_percentage_value)

    def add_throughput_bitrate_stats(self):
        # 315.89 MBit/s (315892951)
        re_bitrate_pattern = re.compile(r"[\d\.]+\s+[\w\/]+\s+\((?P<VALUE>\d+)\)")
        static_marker_params = [
            {
                'data_type': 'decimal',
                'stats_name': 'throughput bitrate'
            },
        ]
        parser = ParserConfig(build_method="throughput",
                              path_to_enb_stats='[protocol][direction]["VALUES"]')

        self._add_rtg_stats(data=self.stats["prRate-C"]["data"],
                            parser=parser,
                            static_marker_params=static_marker_params,
                            marker_template=RTGKPIStats._throughput_marker,
                            pattern=re_bitrate_pattern)

    def add_throughput_packet_rate_stats(self):
        static_marker_params = [
            {
                'data_type': 'decimal',
                'stats_name': 'throughput packet rate'
            },
        ]
        parser = ParserConfig(build_method="throughput",
                              path_to_enb_stats='[protocol][direction]["VALUES"]')

        self._add_rtg_stats(data=self.stats["prPate-C"]["data"],
                            parser=parser,
                            static_marker_params=static_marker_params,
                            marker_template=RTGKPIStats._throughput_marker)

    def add_rrc_reconfiguration_complete_5g_stats(self):
        static_marker_params = [
            {
                'data_type': 'integer',
                'stats_name': 'RRC Reconfiguration Complete 5G'
            },
        ]
        parser = ParserConfig(build_method="sector")

        try:
            rrc_reconf = self.stats['rrcNasSP-C']['data']['endc-MCG-To-SplitSCG-MT']['RRCReconfigurationComplete-5G']
            self._add_rtg_stats(data=rrc_reconf["VALUES"],
                                parser=parser,
                                static_marker_params=static_marker_params,
                                marker_template=RTGKPIStats._sector_marker)
        except KeyError:
            pass

    def add_rrc_reconfiguration_5g_stats(self):
        static_marker_params = [
            {
                'data_type': 'integer',
                'stats_name': 'RRC Reconfiguration 5G'
            },
        ]
        parser = ParserConfig(build_method="sector")

        try:
            rrc_reconf = self.stats['rrcNasSP-C']['data']['endc-MCG-To-SplitSCG-MT']['RRCReconfiguration-5G']
            self._add_rtg_stats(data=rrc_reconf["VALUES"],
                                parser=parser,
                                static_marker_params=static_marker_params,
                                marker_template=RTGKPIStats._sector_marker)
        except KeyError:
            pass

    @staticmethod
    def _add_rtg_stats(data, parser, static_marker_params, marker_template, pattern=None,
                       add_zero_values=False):  # add unit?

        marker_params = {}
        for marker_params, raw_value in parser.build_marker_config(data, marker_params):
            values = RTGKPIStats._get_matched_values(raw_value, pattern) if pattern else [raw_value]
            if values:
                for index, value in enumerate(values):
                    if value or add_zero_values:
                        marker_params.update(static_marker_params[index])
                        value = int(value) if static_marker_params[index]['data_type'] == 'integer' else value
                        RTGKPIStats._add_stats_to_db(value, marker_template, marker_params)

    @staticmethod
    def _get_matched_values(value, pattern):
        match = pattern.search(str(value))
        if match:
            return match.groups()

    @staticmethod
    def _add_stats_to_db(value, marker_template, marker_params):
        marker = marker_template.format(**marker_params)
        tc.add_stats(stats={marker: value})


class ParserConfig(object):
    def __init__(self, build_method, path_to_enb_stats=None):
        self.re_sector = re.compile(r"sector-\d+")
        self.re_enb = re.compile(r"eNB-\d+")
        self.build_method = build_method
        self.path_to_enb_stats = path_to_enb_stats

    def build_marker_config(self, data, marker_config):
        if self.build_method == "throughput":
            build_method = self._build_throughput_marker_config
        elif self.build_method == "procedure":
            build_method = self._build_procedure_marker_config
        elif self.build_method == "sector":
            build_method = self._build_sector_marker_config
        else:
            raise NotImplementedError("{} method is not supported".format(self.build_method))

        return build_method(data, marker_config)

    def _build_throughput_marker_config(self, data, marker_config):
        for protocol in data:
            if protocol == 'All':
                continue
            marker_config['protocol'] = protocol
            for direction in data[protocol]:
                if direction == 'VALUES':
                    continue
                marker_config['direction'] = direction
                for marker_config, value in self._build_sector_marker_config(
                        data=eval("data{}".format(self.path_to_enb_stats)),
                        marker_config=marker_config):
                    yield marker_config, value

    def _build_procedure_marker_config(self, data, marker_config):
        for procedure in data:
            if "_AVG_" in procedure:  # skip procedures contains _AVG_ in name. eg: SCELL_AVG_ACTIVATED
                continue
            marker_config['procedure'] = procedure
            for marker_config, value in self._build_sector_marker_config(
                    data=eval("data{}".format(self.path_to_enb_stats)),
                    marker_config=marker_config):
                yield marker_config, value

    def _build_sector_marker_config(self, data, marker_config):
        for enb in data:
            if self.re_enb.match(enb):
                for sector in data[enb]:
                    if self.re_sector.match(sector):
                        marker_config['device_name'] = enb
                        marker_config['sector'] = sector
                        yield marker_config, data[enb][sector]
